    state: list[str] | None = Field(None, max_length=100, description='US state or territory where a candidate runs for office')
    party: list[str] | None = Field(None, max_length=100, description='Three-letter code for the party affiliated with a candidate or committee. For example, DEM for Democratic Party and REP for Republican Party.')
